/**
 * strategies/team3Reversal/team3ReversalConfig.ts
 *
 * Every setting of Team 3 Reversal: the baseline's sizing, one on/off switch
 * per filter, and the one number each filter is tuned by. With every switch
 * off the strategy is the baseline (fade every regular-session 1-minute bar).
 *
 * Owner: team lead. Teammates read their own knob here but do not edit this file.
 */

import { newId } from "../../utils/ids";
import type { BaseStrategyConfig } from "../../types/strategy";

export interface Team3ReversalConfig extends BaseStrategyConfig {
  type: "team3_reversal";

  // ---- Baseline -------------------------------------------------------
  /** Whole shares per order. */
  qtyPerTrade: number;
  /** Largest absolute share position per symbol; an order past it is skipped. */
  maxPositionQty: number;
  /** How many earlier bars per symbol the filters can look back on. */
  lookbackBars: number;
  /** Trade only 9:30-16:00 ET bars. Other bars still update the history. */
  regularHoursOnly: boolean;

  // ---- Switches: one per filter (all false = baseline) ------------------
  useBigMove: boolean;
  useVolume: boolean;
  useRelativeToSpy: boolean;
  useHoldUntilBack: boolean;
  useTimeOfDay: boolean;

  // ---- Knobs: the one number each filter is tuned by --------------------
  /** bigMove: fade only moves at least this many standard deviations from normal. */
  bigMoveMinZ: number;
  /** volume: skip bars whose volume is more than this many times the recent average. */
  volumeMaxRatio: number;
  /** relativeToSpy: the market symbol to compare against. Must be in `symbols`. */
  benchmarkSymbol: string;
  /** holdUntilBack: always exit after this many bars, even if the price never came back. */
  holdMaxBars: number;
  /** timeOfDay: skip this many minutes after the open and before the close. */
  skipEdgeMinutes: number;
}

export const DEFAULT_TEAM3_REVERSAL_SYMBOLS = [
  "SPY", "QQQ", "NVDA", "AAPL", "MSFT", "MU", "AMD", "AMZN", "META", "GOOGL", "TSLA",
];

export const DEFAULT_TEAM3_REVERSAL_CONFIG: Omit<Team3ReversalConfig, "id" | "symbols"> = {
  name: "Team 3 Reversal",
  type: "team3_reversal",
  // The three fields below satisfy the shared config contract; this strategy ignores them.
  rollingWindowMs: 60_000,
  maxPositionSizeUsd: 10_000,
  cooldownMs: 0,
  enabled: true,

  qtyPerTrade: 1,
  maxPositionQty: 1,
  lookbackBars: 30,
  regularHoursOnly: true,

  useBigMove: false,
  useVolume: false,
  useRelativeToSpy: false,
  useHoldUntilBack: false,
  useTimeOfDay: false,

  bigMoveMinZ: 2,
  volumeMaxRatio: 3,
  benchmarkSymbol: "SPY",
  holdMaxBars: 15,
  skipEdgeMinutes: 15,
};

/** Merges defaults with overrides; a new ID is assigned unless one is given. */
export function createTeam3ReversalConfig(overrides: Partial<Team3ReversalConfig> = {}): Team3ReversalConfig {
  return {
    ...DEFAULT_TEAM3_REVERSAL_CONFIG,
    id: newId(),
    symbols: [...DEFAULT_TEAM3_REVERSAL_SYMBOLS],
    ...overrides,
  };
}

function positiveInt(value: number, name: string): void {
  if (!Number.isInteger(value) || value <= 0) {
    throw new Error(`team3_reversal: ${name} must be a positive whole number (got ${value})`);
  }
}

function positiveNumber(value: number, name: string): void {
  if (typeof value !== "number" || !Number.isFinite(value) || value <= 0) {
    throw new Error(`team3_reversal: ${name} must be a positive number (got ${value})`);
  }
}

/** Throws on a config the strategy cannot trade safely, so a bad one fails when saved. */
export function validateTeam3ReversalConfig(config: Team3ReversalConfig): void {
  if (!Array.isArray(config.symbols) || config.symbols.length === 0) {
    throw new Error("team3_reversal: symbols must be a non-empty list");
  }
  if (config.symbols.some((s) => typeof s !== "string" || s.trim() === "")) {
    throw new Error("team3_reversal: every symbol must be a non-empty ticker");
  }
  positiveInt(config.qtyPerTrade, "qtyPerTrade");
  if (!Number.isInteger(config.maxPositionQty) || config.maxPositionQty < config.qtyPerTrade) {
    throw new Error(
      `team3_reversal: maxPositionQty must be a whole number >= qtyPerTrade (got ${config.maxPositionQty})`,
    );
  }
  positiveInt(config.lookbackBars, "lookbackBars");
  positiveNumber(config.bigMoveMinZ, "bigMoveMinZ");
  positiveNumber(config.volumeMaxRatio, "volumeMaxRatio");
  positiveInt(config.holdMaxBars, "holdMaxBars");
  if (!Number.isInteger(config.skipEdgeMinutes) || config.skipEdgeMinutes < 0) {
    throw new Error(`team3_reversal: skipEdgeMinutes must be a whole number >= 0 (got ${config.skipEdgeMinutes})`);
  }
  if (config.useRelativeToSpy && !config.symbols.includes(config.benchmarkSymbol)) {
    // The strategy only receives bars for its own symbols, so it could never see the benchmark.
    throw new Error(
      `team3_reversal: useRelativeToSpy needs ${config.benchmarkSymbol} in symbols to read its bars`,
    );
  }
}
